    .header-button { color: var(--on-ink); background: var(--ink); border-color: var(--ink); min-height: 44px; padding: var(--space-3) var(--space-4); }
    .header-button:hover { background: var(--on-ink-line); color: var(--on-ink); }
    .hero { padding: var(--space-16) 0 var(--space-12); }
