    .hero-copy { max-width: 46ch; color: var(--muted); font-size: var(--text-lg); line-height: 1.6; }
    .billing { display: flex; flex-shrink: 0; align-items: center; gap: var(--space-3); }
    .billing-switch { display: inline-flex; padding: var(--space-1); border: 1px solid var(--control-line); border-radius: var(--radius); }
