    .plan .button { width: 100%; margin-top: var(--space-6); }
    .button-arrow { margin-left: auto; font-size: var(--text-lg); font-weight: 400; }
    .plan .button { justify-content: flex-start; }
    .plan ul { list-style: none; padding: var(--space-6) 0 0; margin: var(--space-8) 0 0; border-top: 1px solid var(--line); }
