    .plan li::before { content: '✓'; color: var(--accent); font-size: var(--text-sm); font-weight: 600; flex: 0 0 16px; }
    .plan li.unavailable { color: var(--muted); }
    .plan li.unavailable::before { content: '−'; color: var(--muted); font-weight: 400; }
    .plan.popular { color: var(--on-ink); background: var(--ink); border-color: var(--ink); }
    .popular .description, .popular .period, .popular .billing-note, .popular li.unavailable { color: var(--on-ink-muted); }
    .popular ul { border-color: var(--on-ink-line); }
    .popular li::before, .popular li.unavailable::before { color: var(--on-ink-muted); }
    .popular .button { color: var(--ink); background: var(--on-ink); border-color: var(--on-ink); }
    .popular .button:hover { background: var(--accent-soft); border-color: var(--accent-soft); }
    .popular .button:active { background: var(--on-ink-muted); }
    .popular a:focus-visible { outline-color: var(--on-ink); }
    .features { padding: var(--space-24) 0; }
    .section-heading { font-family: var(--serif); font-size: var(--text-heading); font-weight: 400; letter-spacing: -.035em; line-height: 1.15; }
    .feature-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-16); padding-top: var(--space-8); margin-top: var(--space-8); border-top: 1px solid var(--line); }
    .feature-icon { display: block; width: 24px; height: 24px; margin-bottom: var(--space-6); color: var(--accent); fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
    .feature h3 { font-size: var(--text-base); font-weight: 600; margin-bottom: var(--space-2); }
    .feature p { color: var(--muted); font-size: var(--text-sm); max-width: 32ch; line-height: 1.7; }
    .faq { display: grid; grid-template-columns: 1fr 1.6fr; gap: var(--space-16); border-top: 1px solid var(--line); padding: var(--space-16) 0 var(--space-24); }
    .faq .section-heading { max-width: 10ch; }
    details { border-bottom: 1px solid var(--line); }
    details:first-child { border-top: 1px solid var(--line); }
    summary { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); padding: var(--space-6) 0; cursor: pointer; list-style: none; font-size: var(--text-base); }
    summary::-webkit-details-marker { display: none; }
    summary::after { content: '+'; font-size: var(--text-xl); color: var(--muted); font-weight: 400; line-height: 1; }
