      .account { gap: var(--space-4); }
      .account-link { font-size: var(--text-sm); }
      .header-button { padding: var(--space-2) var(--space-3); }
      .navigation { order: 3; width: 100%; margin: var(--space-3) 0 0; gap: var(--space-6); }
      .hero { padding: var(--space-12) 0 var(--space-8); }
      .page-label { margin-bottom: var(--space-4); }
      .hero-copy { font-size: var(--text-base); }
      .plans { grid-template-columns: 1fr; gap: var(--space-4); }
      .plan { padding: var(--space-8); }
      .plan-title { flex-direction: row; align-items: center; min-height: 36px; }
      .price-block { margin-top: var(--space-6); }
      .features { padding: var(--space-16) 0; }
      .section-heading { font-size: 2rem; }
      .feature-grid { grid-template-columns: 1fr; gap: var(--space-8); }
      .feature { display: grid; grid-template-columns: 24px 1fr; column-gap: var(--space-4); }
      .feature-icon { grid-row: span 2; margin: 0; }
      .feature p { max-width: 40ch; }
      .faq { grid-template-columns: 1fr; padding: var(--space-12) 0 var(--space-16); gap: var(--space-8); }
      .faq .section-heading { max-width: none; }
      .footer-inner { flex-direction: column; align-items: flex-start; }
    }
    @media (max-width: 374px) {
      .container { width: calc(100% - var(--space-8)); }
      .account { gap: var(--space-2); }
      .account-link { font-size: .75rem; }
      .brand-mark { width: 20px; }
      .plan { padding: var(--space-6); }
    }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none "'!important; } }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="site-header">
    <div class="container header-inner">
      <a class="wordmark" href="#" aria-label="Marginalia home">
        <svg class="brand-mark" viewBox="0 0 24 28" fill="none" aria-hidden="true"><path d="M5 3v22M10 7h11M10 13h8M10 19h11" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>
        Marginalia
      </a>
      <nav class="navigation" aria-label="Main navigation">
        <a href="#features">Features</a>
        <a href="#pricing" aria-current="page">Pricing</a>
        <a href="#">Blog</a>
      </nav>
      <div class="account">
        <a class="account-link" href="#">Log in</a>
        <a class="button header-button" href="#">Sign up free</a>
      </div>
    </div>
  </header>
  <main id="main" class="container">
    <section class="hero" id="pricing" aria-labelledby="pricing-heading">
      <p class="page-label">Pricing</p>
      <h1 id="pricing-heading">Room for your next idea.</h1>
      <div class="hero-bottom">
        <p class="hero-copy">From your first note to a shared notebook.<br>Choose the space you need.</p>
        <div class="billing">
          <div class="billing-switch" role="group" aria-label="Billing period">
            <button type="button" data-period="monthly" aria-pressed="true">Monthly</button>
            <button type="button" data-period="yearly" aria-pressed="false">Yearly</button>
          </div>
          <span class="saving">Save 20% yearly</span>
        </div>
      </div>
    </section>
    <section class="plans" aria-label="Compare plans">
      <article class="plan" aria-labelledby="starter-heading">
        <div class="plan-title"><h2 id="starter-heading">Starter</h2></div>
        <p class="description">A place to start collecting your thoughts.</p>
        <div class="price-block">
          <p class="price"><span class="amount"><span class="currency">$</span>0</span><span class="period">/ month</span></p>
          <p class="billing-note">Free</p>
