          <li>2 devices</li>
          <li>Basic search</li>
          <li class="unavailable"><span><span class="sr-only">Not included: </span>Offline access</span></li>
          <li class="unavailable"><span><span class="sr-only">Not included: </span>Shared notebooks</span></li>
        </ul>
      </article>
      <article class="plan popular" aria-labelledby="pro-heading">
        <div class="plan-title"><h2 id="pro-heading">Pro</h2><span class="badge">Most popular</span></div>
        <p class="description">For a growing collection of ideas.</p>
        <div class="price-block">
          <p class="price"><span class="amount"><span class="currency">$</span><span data-price="pro">8</span></span><span class="period">/ month</span></p>
          <p class="billing-note" data-billing="pro">Billed monthly</p>
        </div>
        <a class="button" href="#" aria-label="Get started with Pro">Get Pro <span class="button-arrow" aria-hidden="true">↗</span></a>
        <ul>
          <li>Unlimited notes</li>
          <li>Unlimited devices</li>
          <li>Full-text search inside PDFs</li>
          <li>Offline access</li>
          <li class="unavailable"><span><span class="sr-only">Not included: </span>Shared notebooks</span></li>
        </ul>
      </article>
      <article class="plan" aria-labelledby="team-heading">
        <div class="plan-title"><h2 id="team-heading">Team</h2></div>
        <p class="description">A shared space to think together.</p>
        <div class="price-block">
          <p class="price"><span class="amount"><span class="currency">$</span><span data-price="team">14</span></span><span class="period">/ user / month</span></p>
          <p class="billing-note" data-billing="team">Billed monthly</p>
        </div>
        <a class="button" href="#" aria-label="Get started with Team">Get Team <span class="button-arrow" aria-hidden="true">↗</span></a>
        <ul>
          <li>Everything in Pro</li>
          <li>Shared notebooks</li>
          <li>Admin controls</li>
          <li>Priority support</li>
          <li>SSO</li>
        </ul>
      </article>
    </section>
    <p class="sr-only" role="status" id="billing-status"></p>
    <section class="features" id="features" aria-labelledby="features-heading">
      <h2 class="section-heading" id="features-heading">Your notes, in good order.</h2>
      <div class="feature-grid">
        <div class="feature">
          <svg class="feature-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5M8 10.5h5"/></svg>
          <h3>Find the thought</h3><p>Fast search brings the note you'"'re looking for back into view.</p>
        </div>
        <div class=\"feature\">
          <svg class=\"feature-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"5\" y=\"10\" width=\"14\" height=\"11\" rx=\"2\"/><path d=\"M8 10V7a4 4 0 0 1 8 0v3M12 14v3\"/></svg>
          <h3>Keep it safe</h3><p>Your notes are encrypted, so your ideas stay protected.</p>
        </div>
        <div class=\"feature\">
          <svg class=\"feature-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 8a8 8 0 0 0-13-3L3 9m0-5v5h5M4 16a8 8 0 0 0 13 3l4-4m0 5v-5h-5\"/></svg>
          <h3>Pick up anywhere</h3><p>Sync your notes across your devices and keep your ideas close.</p>
        </div>
      </div>
    </section>
    <section class=\"faq\" aria-labelledby=\"faq-heading\">
      <h2 class=\"section-heading\" id=\"faq-heading\">A few good questions.</h2>
      <div>
        <details open><summary>Can I cancel anytime?</summary><p>Yes. You can cancel your subscription at any time, no questions asked.</p></details>
        <details><summary>Is there a free trial for Pro?</summary><p>Yes, Pro comes with a 14-day free trial. No credit card required.</p></details>
        <details><summary>Do you offer student discounts?</summary><p>Students get 50% off Pro with a valid school email.</p></details>
      </div>
    </section>
  </main>
  <footer class=\"site-footer\">
    <div class=\"container footer-inner\">
      <span class=\"wordmark\">Marginalia</span>
      <p class=\"copyright\">© 2026 Marginalia Inc. All rights reserved.</p>
    </div>
  </footer>
  <script>
    // Annual prices use the existing 20% yearly discount.
    const monthlyPrices = { pro: 8, team: 14 };
    const billingButtons = document.querySelectorAll('[data-period]');
    billingButtons.forEach(button => {
      button.addEventListener('click', () => {
        const yearly = button.dataset.period === 'yearly';
        billingButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
        Object.entries(monthlyPrices).forEach(([plan, monthly]) => {
          const price = yearly ? monthly * 0.8 : monthly;
          document.querySelector("'`[data-price="${plan}"]`).textContent = yearly ? price.toFixed(2) : String(price);
          document.querySelector(`[data-billing="${plan}"]`).textContent = yearly
            ? `$${(price * 12).toFixed(2)}${plan === '"'team' ? ' per user' : ''}, billed yearly"'`
            : '"'Billed monthly';
        });
        document.getElementById('billing-status').textContent = yearly
          ? 'Yearly billing selected. Pro: "'$6.40 per month, $76.80 billed yearly. Team: $11.20 per user per month, $134.40 per user billed yearly.'"'
          : 'Monthly billing selected. Pro: "'$8 per month. Team: $14 per user per month.'"';
      });
    });
  </script>
</body>
</html>
