    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a: self.ids.append(a['id'])
        if tag=='a' and a.get('href','').startswith('#') and a['href']"'!='"'#': self.anchors.append(a['href'][1:])
        if tag in ['h1','h2','h3']: self.headings.append(tag)
        if tag=='details': self.details+=1
        if tag=='html': self.lang=a.get('lang')=='en'
        if tag=='meta' and a.get('name')=='viewport': self.viewport=True
p=Check();p.feed(open('index.html').read())
assert len(p.ids)==len(set(p.ids))
assert all(a in p.ids for a in p.anchors)
assert p.headings.count('h1')==1 and p.details==3 and p.lang and p.viewport
print('PASS: unique IDs, section anchors, heading structure, native FAQ controls, language and mobile viewport.')
